CREATE TABLE IF NOT EXISTS locations (id BIGINT AUTO_INCREMENT PRIMARY KEY, streetName VARCHAR(255) NOT NULL, houseNumber VARCHAR(20) NOT NULL, houseNumberAddition VARCHAR(20) NULL, postalCode VARCHAR(20) NOT NULL, city VARCHAR(100) NOT NULL, country VARCHAR(100) NOT NULL, userId BIGINT NOT NULL, CONSTRAINT fk_locations_userId__id FOREIGN KEY (userId) REFERENCES users(id) ON DELETE CASCADE ON UPDATE RESTRICT);

